import boto3
import datetime

def summarize_federated_login_events(num_events=100):
    """
    Summarizes recent AWS CloudTrail events related to federated logins.
    """
    client = boto3.client('cloudtrail')

    # Define a time window for the events (e.g., last 7 days)
    end_time = datetime.datetime.now()
    start_time = end_time - datetime.timedelta(days=7)

    federated_events = []
    paginator = client.get_paginator('lookup_events')
    pages = paginator.paginate(
        LookupAttributes=[
            {
                'AttributeKey': 'EventName',
                'AttributeValue': 'FederatedLogin'
            },
        ],
        StartTime=start_time,
        EndTime=end_time,
        MaxResults=num_events
    )

    for page in pages:
        for event in page['Events']:
            federated_events.append(event)
        if len(federated_events) >= num_events:
            break

    summary = {
        "total_federated_login_events": len(federated_events),
        "events": []
    }

    for event in federated_events:
        summary_event = {
            "event_id": event.get('EventId'),
            "event_name": event.get('EventName'),
            "event_source": event.get('EventSource'),
            "username": event.get('Username'),
            "event_time": event.get('EventTime').isoformat() if event.get('EventTime') else None,
            "aws_region": event.get('AwsRegion')
        }
        summary['events'].append(summary_event)

    return summary

if __name__ == "__main__":
    summary = summarize_federated_login_events(num_events=50)
    print("Federated Login Event Summary:")
    print(f"Total events found: {summary['total_federated_login_events']}")
    for event in summary['events']:
        print(f"  Event ID: {event['event_id']}, User: {event['username']}, Time: {event['event_time']}, Region: {event['aws_region']}")

import os
import requests
import json
from urllib.parse import urlencode

# Configuration from environment variables
CLIENT_ID = os.getenv("IDENTITY_CLIENT_ID", "your_client_id")
CLIENT_SECRET = os.getenv("IDENTITY_CLIENT_SECRET", "your_client_secret")
REDIRECT_URI = os.getenv("IDENTITY_REDIRECT_URI", "http://localhost:8000/callback")
AUTHORIZATION_URL = os.getenv("IDENTITY_AUTHORIZATION_URL", "https://example.com/oauth2/authorize")
TOKEN_URL = os.getenv("IDENTITY_TOKEN_URL", "https://example.com/oauth2/token")
USERINFO_URL = os.getenv("IDENTITY_USERINFO_URL", "https://example.com/oauth2/userinfo")
SCOPE = os.getenv("IDENTITY_SCOPE", "openid profile email") # Default scopes

class IdentityClient:
    def __init__(self, client_id=CLIENT_ID, client_secret=CLIENT_SECRET,
                 redirect_uri=REDIRECT_URI, authorization_url=AUTHORIZATION_URL,
                 token_url=TOKEN_URL, userinfo_url=USERINFO_URL, scope=SCOPE):
        self.client_id = client_id
        self.client_secret = client_secret
        self.redirect_uri = redirect_uri
        self.authorization_url = authorization_url
        self.token_url = token_url
        self.userinfo_url = userinfo_url
        self.scope = scope

    def get_authorization_url(self, state=None):
        """Constructs the authorization URL for initiating the federated login flow."""
        params = {
            "response_type": "code",
            "client_id": self.client_id,
            "redirect_uri": self.redirect_uri,
            "scope": self.scope,
        }
        if state:
            params["state"] = state
        return f"{self.authorization_url}?{urlencode(params)}"

    def exchange_code_for_token(self, code):
        """Exchanges the authorization code for an access token."""
        headers = {
            "Content-Type": "application/x-www-form-urlencoded"
        }
        data = {
            "grant_type": "authorization_code",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "code": code,
            "redirect_uri": self.redirect_uri,
        }
        try:
            response = requests.post(self.token_url, headers=headers, data=data)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error exchanging code for token: {e}")
            return None

    def get_user_info(self, access_token):
        """Fetches user information using the access token."""
        headers = {
            "Authorization": f"Bearer {access_token}"
        }
        try:
            response = requests.get(self.userinfo_url, headers=headers)
            response.raise_for_status()
            return response.json()
        except requests.exceptions.RequestException as e:
            print(f"Error fetching user info: {e}")
            return None

import os
from flask import Flask, redirect, url_for, session, request
from google_auth_oauthlib.flow import Flow
import google.oauth2.credentials

app = Flask(__name__)
app.secret_key = os.urandom(24)

# Replace with your Google API client ID and client secret
CLIENT_SECRETS_FILE = "client_secret.json" # You would typically load this from a file or environment variables
# For demonstration, let's assume a simplified client_secret.json structure for clarity
# In a real application, you'd have a proper client_secret.json file downloaded from Google Cloud Console.

# Dummy values for demonstration purposes, replace with your actual values
CLIENT_ID = os.environ.get("GOOGLE_CLIENT_ID", "YOUR_GOOGLE_CLIENT_ID")
CLIENT_SECRET = os.environ.get("GOOGLE_CLIENT_SECRET", "YOUR_GOOGLE_CLIENT_SECRET")
REDIRECT_URI = os.environ.get("GOOGLE_REDIRECT_URI", "http://localhost:5000/oauth_callback")

SCOPES = ['https://www.googleapis.com/auth/userinfo.email', 'https://www.googleapis.com/auth/userinfo.profile']

@app.route("/authorize")
def authorize():
    flow = Flow.from_client_config(
        client_config={
            "web": {
                "client_id": CLIENT_ID,
                "client_secret": CLIENT_SECRET,
                "auth_uri": "https://accounts.google.com/o/oauth2/auth",
                "token_uri": "https://oauth2.googleapis.com/token",
                "redirect_uris": [REDIRECT_URI]
            }
        },
        scopes=SCOPES,
        redirect_uri=REDIRECT_URI
    )

    authorization_url, state = flow.authorization_url(
        access_type='offline',
        include_granted_scopes='true'
    )

    session['oauth_state'] = state
    return redirect(authorization_url)

@app.route("/oauth_callback")
def oauth_callback():
    state = session.pop('oauth_state', None)

    flow = Flow.from_client_config(
        client_config={
            "web": {
                "client_id": CLIENT_ID,
                "client_secret": CLIENT_SECRET,
                "auth_uri": "https://accounts.google.com/o/oauth2/auth",
                "token_uri": "https://oauth2.googleapis.com/token",
                "redirect_uris": [REDIRECT_URI]
            }
        },
        scopes=SCOPES,
        state=state,
        redirect_uri=REDIRECT_URI
    )

    try:
        flow.fetch_token(authorization_response=request.url)
        credentials = flow.credentials
        session['credentials'] = {
            'token': credentials.token,
            'refresh_token': credentials.refresh_token,
            'token_uri': credentials.token_uri,
            'client_id': credentials.client_id,
            'client_secret': credentials.client_secret,
            'scopes': credentials.scopes
        }
        return "Authentication successful! Tokens stored in session."
    except Exception as e:
        return f"Authentication failed: {e}"

@app.route("/")
def index():
    if 'credentials' not in session:
        return '<p>You are not logged in. <a href="/authorize">Log in with Google</a></p>'
    return '<p>Logged in. <a href="/logout">Log out</a></p>'

@app.route("/logout")
def logout():
    session.pop('credentials', None)
    return redirect(url_for('index'))

if __name__ == "__main__":
    # Ensure you have set GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, and GOOGLE_REDIRECT_URI
    # in your environment variables or replace the dummy values above.
    # For local testing, you might need to install flask and google-auth-oauthlib:
    # pip install Flask google-auth-oauthlib google-api-python-client
    app.run(debug=True)
